const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakes = ee.Geometry.Polygon(
    [[[-93.2, 49.3], [-93.2, 41.0], [-75.8, 41.0], [-75.8, 49.3]]],
    null, false
  );

  const date1_start = '2021-02-20';
  const date1_end = '2021-02-21'; // Single day
  const date2_start = '2021-03-03';
  const date2_end = '2021-03-04'; // Single day

  const collectionId = 'MODIS/061/MOD10A1';
  const bandName = 'Snow_Cover_Daily_Tile'; // Values: 200 (Snow), 25 (Water), 50 (Cloud), 254 (Lake)

  // Function to process image for a given date range
  const getImageAndIceArea = async (startDate, endDate, periodName) => {
    let collection = ee.ImageCollection(collectionId)
      .filterBounds(greatLakes)
      .filterDate(startDate, endDate)
      .select(bandName);

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${periodName} (${startDate} to ${endDate}).`);
      return { image: null, iceArea: null, pixelCount: 0 };
    }

    // Try to get a representative image. Take the first if multiple, or mosaic if desired.
    // For single-day query, taking the first is usually sufficient.
    let image = collection.first();

    // Define masks for specific values
    const cloudMask = image.neq(50); // Mask out clouds
    const lakeMask = image.eq(254); // Identify lake pixels
    const snowIceMask = image.eq(200); // Identify snow/ice pixels within lakes

    // Combine masks: Must be a lake pixel AND be classified as snow/ice AND not a cloud
    const iceInLakes = lakeMask.and(snowIceMask).and(cloudMask);

    // Calculate total ice-covered pixel count (which will be proportional to area)
    // Scale for MOD10A1 is 500m. Area per pixel = 500m * 500m = 250,000 sq meters = 0.25 sq km
    const icePixelCount = iceInLakes.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: greatLakes,
      scale: 500, // MODIS resolution
      maxPixels: 1e9,
      crs: image.projection().crs() // Ensure projection is consistent
    }).get(bandName);

    const iceCountValue = await icePixelCount.getInfo();

    if (iceCountValue === null) {
      console.log(`Calculation for ${periodName} failed to return a value.`);
      return { image: image, iceArea: null, pixelCount: 0 };
    }

    const validPixelsTotal = await image.updateMask(cloudMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: greatLakes,
      scale: 500,
      maxPixels: 1e9,
      crs: image.projection().crs()
    }).get(bandName).getInfo();

    const actualIceAreaSqKm = iceCountValue * 0.25;

    console.log(`${periodName} Image: ${collectionSize}, Valid Pixels (after cloud mask): ${validPixelsTotal}`);
    return { image: image, iceArea: actualIceAreaSqKm, pixelCount: iceCountValue };
  };

  // 2. Data Acquisition & Check for Period 1
  const result1 = await getImageAndIceArea(date1_start, date1_end, 'Feb 20, 2021');
  if (result1.image === null) {
    console.log("C1");
    return;
  }
  if (result1.pixelCount === 0) {
    console.log(`No valid ice pixels found for Feb 20, 2021 after processing.`);
    console.log("C2");
    return;
  }
  if (result1.iceArea === null) {
    console.log("C3");
    return;
  }

  // 2. Data Acquisition & Check for Period 2
  const result2 = await getImageAndIceArea(date2_start, date2_end, 'Mar 3, 2021');
  if (result2.image === null) {
    console.log("C1");
    return;
  }
  if (result2.pixelCount === 0) {
    console.log(`No valid ice pixels found for Mar 3, 2021 after processing.`);
    console.log("C2");
    return;
  }
  if (result2.iceArea === null) {
    console.log("C3");
    return;
  }

  // 3. Comparison and Final Answer
  const iceArea1 = result1.iceArea;
  const iceArea2 = result2.iceArea;

  console.log(`Ice coverage on Feb 20, 2021: ${iceArea1.toFixed(2)} sq km`);
  console.log(`Ice coverage on Mar 3, 2021: ${iceArea2.toFixed(2)} sq km`);

  if (iceArea2 < iceArea1) {
    console.log("A"); // Yes, ice coverage decreased
  } else {
    console.log("B"); // No, ice coverage did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
